#!/usr/bin/env bash
# Writes src/config.js from environment variables at build time.
# Values are public (IDs and URLs). Never add a secret here.
set -euo pipefail

: "${TENANT_ID:?TENANT_ID is required}"
: "${UI_CLIENT_ID:?UI_CLIENT_ID is required}"
: "${API_BASE_URL:?API_BASE_URL is required}"
: "${API_SCOPE:?API_SCOPE is required}"

OUT="${1:-src/config.js}"
cat > "$OUT" <<JS
// Generated by scripts/render-config.sh. Public values only.
window.POKEDEX_CONFIG = {
  tenantId: "${TENANT_ID}",
  clientId: "${UI_CLIENT_ID}",
  apiBaseUrl: "${API_BASE_URL}",
  apiScope: "${API_SCOPE}"
};
JS
echo "Wrote $OUT"
